using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Observer.ProbabilisticClosure.TrajectoryLaws.ReadExecution;

internal sealed class ActualRenewalStoppingDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Actual renewal bits and arbitrary per-bit updates retain the stopping label and pay for live epochs.",
        H("Actual renewal stopping correspondence"),
        Blocks(
            Describe.Lean(
                DescribeId.Create("actual-renewal-source-words"),
                DeclarationHandle.Create(
                    "D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/ReadExecution/ActualRenewalStopping.source_words"),
                H("The literal source words"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("For every natural initial wait u and every sequence K of natural zero counts, define c(0)=u+1 and c(n+1)=c(n)+K(n)+1. The source bit X(t) is generated by searching the finite set of n<t+1 for c(n)=t+1. This places the closing tick at absolute index c(n)-1. The proof derives strict increase and c(n)>=n+1 from this recursion.")),
                    Paragraph(Text("Every bit before u is zero, X(u)=1, and for every n and every 0<=k<=K(n), X(c(n)+k) is one exactly when k=K(n). Also X(c(n)-1)=1 for every n. Thus the same history is the initial u zeros and tick, followed by the consecutive K(n)-zero/one-tick words. Empty zero words and zero initial wait are included. No tick-count identity or source Markov law is assumed.")),
                    Paragraph(Text("The clock is an external proof coordinate and is not supplied to an observer update. The specialized marked-block clock in CriticalRenewalPaths belongs to its counted controller; no dummy marked trace is introduced to represent the arbitrary observer here."))),
                DescribeRole.Theorem),
            Describe.Lean(
                DescribeId.Create("actual-renewal-stopping-correspondence"),
                DeclarationHandle.Create(
                    "D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/ReadExecution/ActualRenewalStopping.stopping_correspondence"),
                H("Actual first stopping and the first terminal epoch"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("Quantify arbitrary state and coin types S,R, a terminal-state set L, a raw update S times Bool times R to S, an initial state z, a coin sequence r, an initial wait u, and a sequence K of finite natural zero counts. Z(0)=z. At time t, if Z(t) is in L the analytical continuation holds that state fixed; otherwise the sole successor is update(Z(t),X(t),r(t)). In particular the update receives no external time, gap, clock or unused coin suffix. Y(n)=Z(c(n)) samples this very run after the actual n-th tick. These statements apply to any finite observer and to every realization of its initialization and update randomness; no probabilistic independence or distribution is asserted here.")),
                    Paragraph(Text("Use the existing FreshServiceRestart.firstHit, including index zero and the none nontermination value, for both Z and Y. Define Q(T) as the sum of the actual Boolean bits X(t) over exactly t<T, with one charged for true and zero for false. For every T with firstHit(L,Z)=some T there exists N with firstHit(L,Y)=some N, Y(N)=Z(T), T<=c(N), c(n)<T for every n<N, N<=Q(T)<=T, and N=0 if and only if T<=u+1. In addition firstHit(L,Z)=none if and only if firstHit(L,Y)=none.")),
                    Paragraph(Text("Pointwise persistence of the emitted state is proved by induction on the raw per-bit recursion. The construction takes the least n with T<=c(n); the lower bound on c supplies existence. Minimality and the original first-hit characterization identify exactly the first terminal epoch. Each n<N then supplies the distinct already read tick c(n)-1<T. Injecting these ticks into the actual paid-bit set proves N<=Q(T), and that set is contained in the T read positions.")),
                    Paragraph(Text("An initial label has T=0,N=0,Q(T)=0. A stop during the initial zeros or immediately after the first tick has N=0. A stop during later zeros is recorded at the next analytical tick with the same frozen label; that tick need not have been read. A tick at absolute index T is excluded from Q(T). Stopping on a read tick means T=c(n), whereas stopping before that tick means T<=c(n)-1. Neither case adds a suffix payment. Consecutive ticks, arbitrary zero transition entries in a later stochastic realization, and nontermination are not excluded.")),
                    Paragraph(Text("This is the deterministic actual-stopping part of the live-epoch argument in the entropy-harmonic renewal state-threshold theory. ActualRenewalPrefixLaw and ActualRenewalHistoryLaw derive finite-word integration, raw-past freshness, initialization, ordinary-history locality and all-length source/state cylinders under explicit deterministic-coordinate product and effective sampler-row interfaces on this same run. The original source PMFs, the common observer realization for both targets, real-matrix identification, occupation expectations, predictable payment, harmonic separation and the full original E4 entropy bound remain separate obligations. No termination or finite mean of an auxiliary W chain is used."))),
                DescribeRole.Theorem))));
}
